func testImpostosUpdate(t *testing.T) {
	t.Parallel()

	if 0 == len(impostoPrimaryKeyColumns) {
		t.Skip("Skipping table with no primary key columns")
	}
	if len(impostoAllColumns) == len(impostoPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &Imposto{}
	if err = randomize.Struct(seed, o, impostoDBTypes, true, impostoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Imposto struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := Impostos().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, impostoDBTypes, true, impostoPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize Imposto struct: %s", err)
	}

	if rowsAff, err := o.Update(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("should only affect one row but affected", rowsAff)
	}
}

func testImpostosSliceUpdateAll(t *testing.T) {
	t.Parallel()

	if len(impostoAllColumns) == len(impostoPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &Imposto{}
	if err = randomize.Struct(seed, o, impostoDBTypes, true, impostoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Imposto struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := Impostos().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, impostoDBTypes, true, impostoPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize Imposto struct: %s", err)
	}

	// Remove Primary keys and unique columns from what we plan to update
	var fields []string
	if strmangle.StringSliceMatch(impostoAllColumns, impostoPrimaryKeyColumns) {
		fields = impostoAllColumns
	} else {
		fields = strmangle.SetComplement(
			impostoAllColumns,
			impostoPrimaryKeyColumns,
		)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	typ := reflect.TypeOf(o).Elem()
	n := typ.NumField()

	updateMap := M{}
	for _, col := range fields {
		for i := 0; i < n; i++ {
			f := typ.Field(i)
			if f.Tag.Get("boil") == col {
				updateMap[col] = value.Field(i).Interface()
			}
		}
	}

	slice := ImpostoSlice{o}
	if rowsAff, err := slice.UpdateAll(ctx, tx, updateMap); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("wanted one record updated but got", rowsAff)
	}
}

func testImpostosUpsert(t *testing.T) {
	t.Parallel()

	if len(impostoAllColumns) == len(impostoPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}
	if len(mySQLImpostoUniqueColumns) == 0 {
		t.Skip("Skipping table with no unique columns to conflict on")
	}

	seed := randomize.NewSeed()
	var err error
	// Attempt the INSERT side of an UPSERT
	o := Imposto{}
	if err = randomize.Struct(seed, &o, impostoDBTypes, false); err != nil {
		t.Errorf("Unable to randomize Imposto struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Upsert(ctx, tx, boil.Infer(), boil.Infer()); err != nil {
		t.Errorf("Unable to upsert Imposto: %s", err)
	}

	count, err := Impostos().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 1 {
		t.Error("want one record, got:", count)
	}

	// Attempt the UPDATE side of an UPSERT
	if err = randomize.Struct(seed, &o, impostoDBTypes, false, impostoPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize Imposto struct: %s", err)
	}

	if err = o.Upsert(ctx, tx, boil.Infer(), boil.Infer()); err != nil {
		t.Errorf("Unable to upsert Imposto: %s", err)
	}

	count, err = Impostos().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 1 {
		t.Error("want one record, got:", count)
	}
}
